export interface PolymarketOutcome {
  title: string;
  /** Implied probability of "Yes" (Polymarket's displayed mid price). */
  p: number;
  yesTokenId: string | null;
}

export interface PolymarketEvent {
  slug: string;
  volumeUsd: number | undefined;
  outcomes: PolymarketOutcome[];
}

/** Parses a gamma-api `/events?slug=` response into open outcomes with a valid price. */
export function parsePolymarketEvent(json: unknown): PolymarketEvent {
  const [event] = EventsSchema.parse(json);
  if (!event) throw new Error('event not found');
  const outcomes: PolymarketOutcome[] = [];
  for (const m of event.markets) {
    if (m.closed || m.active === false) continue;
    const p = Number(m.outcomePrices?.[0]);
    if (!Number.isFinite(p) || p < 0 || p > 1) continue;
    outcomes.push({ title: m.groupItemTitle, p, yesTokenId: m.clobTokenIds?.[0] ?? null });
  }
  return { slug: event.slug, volumeUsd: event.volume, outcomes };
}

/** Finds an outcome whose title contains `needle` (case-insensitive). */
export function findOutcome(event: PolymarketEvent, needle: string): PolymarketOutcome | undefined {
  const n = needle.toLowerCase();
  return event.outcomes.find((o) => o.title.toLowerCase().includes(n));
}

const HistorySchema = z.object({
  history: z.array(z.object({ t: z.number(), p: z.number().min(0).max(1) })),
});

/** Parses a CLOB `/prices-history` response. */
export function parsePolymarketHistory(json: unknown): Point[] {
  return HistorySchema.parse(json).history.map(({ t, p }) => ({ t: Math.round(t), p }));
}
